create or replace function public.validar_liberacion_calidad_op() returns trigger language plpgsql set search_path='' as $$ declare v_sede uuid; begin select sede_id into v_sede from public.ordenes_produccion where id=new.orden_produccion_id; if not public.ve_sede(auth.uid(), v_sede) then raise exception 'No tienes acceso a la orden de producción'; end if; if new.resultado='aprobado' and new.tipo='inspeccion_final' then update public.ordenes_produccion set estado='terminada', fecha_fin=coalesce(fecha_fin, now()), updated_at=now() where id=new.orden_produccion_id and estado in ('en_produccion','control_calidad','liberada'); end if; return new; end; $$;
drop trigger if exists trg_validar_liberacion_calidad on public.control_calidad;
create trigger trg_validar_liberacion_calidad after insert on public.control_calidad for each row execute function public.validar_liberacion_calidad_op();
revoke execute on function public.validar_liberacion_calidad_op() from public,anon,authenticated;